/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=note, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2NoteGetParams = {
  resource: 'note';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the note to get
 * @default 0
 */
    noteId?: number | Expression<number>;
};

export type PipedriveV2NoteGetOutput = {
  active_flag?: boolean;
  add_time?: string;
  content?: string;
  deal?: {
    title?: string;
  };
  deal_id?: number;
  id?: number;
  last_update_user_id?: unknown;
  lead?: unknown;
  lead_id?: unknown;
  org_id?: number;
  organization?: {
    name?: string;
  };
  person?: {
    name?: string;
  };
  person_id?: number;
  pinned_to_deal_flag?: boolean;
  pinned_to_lead_flag?: boolean;
  pinned_to_organization_flag?: boolean;
  pinned_to_person_flag?: boolean;
  pinned_to_project_flag?: boolean;
  pinned_to_task_flag?: boolean;
  project_id?: unknown;
  task_id?: unknown;
  update_time?: string;
  user?: {
    email?: string;
    icon_url?: unknown;
    is_you?: boolean;
    name?: string;
  };
  user_id?: number;
};

export type PipedriveV2NoteGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2NoteGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2NoteGetOutput>;
};